<template><aside class="mypage-sidebar" aria-label="마이페이지 메뉴"><div class="sidebar-title"><span>MY MENU</span><strong>마이페이지</strong></div><nav><RouterLink v-for="menu in menus" :key="menu.link" :to="menu.link" class="mypage-nav-link" :class="{active:isActive(menu.link)}"><i :class="menu.icon" aria-hidden="true"></i><span>{{menu.name}}</span><i class="fa-solid fa-chevron-right arrow" aria-hidden="true"></i></RouterLink></nav><div class="sidebar-support"><i class="fa-regular fa-circle-question" aria-hidden="true"></i><p><strong>도움이 필요하신가요?</strong><span>고객센터 042-822-2581</span></p></div><button type="button" class="sidebar-logout" @click="logout"><i class="fa-solid fa-arrow-right-from-bracket" aria-hidden="true"></i> 로그아웃</button></aside></template>
<script setup>import{useRoute,useRouter}from"vue-router";import{useStore}from"vuex";const route=useRoute(),router=useRouter(),store=useStore();const menus=[{name:"마이페이지 홈",link:"/mypage",icon:"fa-solid fa-house"},{name:"회원 정보",link:"/mypage/info",icon:"fa-regular fa-user"},{name:"주문 관리",link:"/mypage/orders",icon:"fa-solid fa-box"},{name:"배송지 관리",link:"/mypage/address",icon:"fa-solid fa-location-dot"},{name:"주문 내역",link:"/mypage/order-history",icon:"fa-solid fa-receipt"},{name:"문의 내역",link:"/mypage/inquiries",icon:"fa-regular fa-comments"}];const isActive=link=>link==="/mypage"?route.path==="/mypage":route.path.startsWith(link);const logout=async()=>{await store.dispatch("logout");router.push("/")};</script>
<style>.mypage-sidebar{position:sticky;top:112px;align-self:start;padding:25px 20px;background:#fff;border:1px solid #e8e1de}.sidebar-title{padding:0 8px 20px;border-bottom:1px solid var(--color-line)}.sidebar-title span,.sidebar-title strong{display:block}.sidebar-title span{color:var(--color-accent);font-size:.55rem;font-weight:800;letter-spacing:.15em}.sidebar-title strong{margin-top:3px;font-family:Georgia,"Noto Serif KR",serif;font-size:1.15rem}.mypage-sidebar nav{padding:13px 0}.mypage-nav-link{display:grid;grid-template-columns:24px 1fr 10px;align-items:center;padding:12px 8px;color:#756b70;font-size:.73rem}.mypage-nav-link>i:first-child{color:#a69ca1;font-size:.78rem}.mypage-nav-link .arrow{opacity:0;color:var(--color-accent);font-size:.48rem}.mypage-nav-link:hover,.mypage-nav-link.active{color:var(--color-brand-dark);background:#f8f4f2;font-weight:700}.mypage-nav-link:hover .arrow,.mypage-nav-link.active .arrow{opacity:1}.sidebar-support{display:flex;gap:10px;padding:15px 10px;background:#f6f3f1;color:#8e8489}.sidebar-support>i{margin-top:2px;color:var(--color-accent)}.sidebar-support strong,.sidebar-support span{display:block}.sidebar-support strong{color:#655b60;font-size:.66rem}.sidebar-support span{margin-top:2px;font-size:.58rem}.sidebar-logout{width:100%;margin-top:15px;padding:10px;border:0;background:transparent;color:#9a9095;font-size:.65rem}.sidebar-logout i{margin-right:6px}@media(max-width:900px){.mypage-sidebar{position:static;padding:0;border-inline:0;overflow-x:auto}.sidebar-title,.sidebar-support,.sidebar-logout{display:none}.mypage-sidebar nav{display:flex;padding:0}.mypage-nav-link{flex:0 0 auto;display:flex;gap:7px;padding:14px 16px;border-bottom:2px solid transparent}.mypage-nav-link .arrow{display:none}.mypage-nav-link.active{border-bottom-color:var(--color-brand);background:#fff}}</style>
